// Yard logo. Mirrors `DesignSystem/YardLogo.swift`.
//
// The hand-drawn brush "YARD" (with its underline swoosh and trademark sign), drawn from the
// website's SVG paths (src/components/brand/yard-logo-paths.ts). The paths live in a 3297 x 1289
// box under the transform "translate(0 1289) scale(0.1 -0.1)" (potrace output, y flipped).
// Parsed with androidx `PathParser` (the iOS app ports its own SVGPathParser).
//
//   YardLogo(Modifier.height(28.dp))                          // acid, keeps aspect
//   YardLogo(Modifier.width(120.dp), color = Color.yard.onAcid)
//   Modifier.background(color, YardLogoShape)                  // the raw Shape
//
// Colour: acid on dark surfaces, black (onAcid) on acid. On light backgrounds use ink.

/** The logo as a [Shape]: fills the given size, aspect-fit and centred. */
object YardLogoShape : Shape {
    /** Width over height of the logo's box (3297 / 1289). */
    const val ASPECT_RATIO: Float = 3297f / 1289f

    /** The logo in its 3297 x 1289 viewBox (SVG transform applied), parsed once. */
    val unitPath: Path by lazy {
        val combined = Path()
        // SVG: translate(0 1289) scale(0.1 -0.1)  →  x' = 0.1x, y' = 1289 - 0.1y
        val m = Matrix()
        m.translate(0f, 1289f)
        m.scale(0.1f, -0.1f)
        for (d in pathData) {
            val p = PathParser().parsePathString(d).toPath()
            p.transform(m)
            combined.addPath(p)
        }
        combined.fillType = PathFillType.NonZero
        combined
    }

    /** The path scaled aspect-fit into [size]. */
    fun path(size: Size): Path {
        val result = Path()
        if (size.width <= 0f || size.height <= 0f) return result
        val scale = min(size.width / 3297f, size.height / 1289f)
        val dx = (size.width - 3297f * scale) / 2f
        val dy = (size.height - 1289f * scale) / 2f
        val m = Matrix()
        m.translate(dx, dy)
        m.scale(scale, scale)
        result.addPath(unitPath)
        result.transform(m)
        return result
    }

