/** The logo view: an aspect-fit [YardLogoShape] filled with [color] (default acid). Size it with a height or width. */
@Composable
fun YardLogo(modifier: Modifier = Modifier, color: Color = Color.yard.acid) {
    Canvas(
        modifier
            .aspectRatio(YardLogoShape.ASPECT_RATIO)
            .semantics { contentDescription = "Yard" },
    ) {
        val s = min(size.width / 3297f, size.height / 1289f)
        translate((size.width - 3297f * s) / 2f, (size.height - 1289f * s) / 2f) {
            scale(s, s, pivot = androidx.compose.ui.geometry.Offset.Zero) {
                drawPath(YardLogoShape.unitPath, color)
            }
        }
    }
}
